function validate([pizza, k]) {
  if (!Array.isArray(pizza) || pizza.length < 1 || pizza.length > 50) return 'pizza needs 1 to 50 rows.';
  const cols = typeof pizza[0] === 'string' ? pizza[0].length : 0;
  if (cols < 1 || cols > 50) return 'Each row needs 1 to 50 cells.';
  for (const row of pizza) {
    if (typeof row !== 'string' || row.length !== cols) return 'All rows must have the same length.';
    if (!/^[A.]+$/.test(row)) return "Cells are 'A' or '.' only.";
  }
  if (!Number.isInteger(k) || k < 1 || k > 10) return 'k is between 1 and 10.';
  return null;
}

