function ways(pizza, k) {
  const MOD = 1e9 + 7;
  const rows = pizza.length;
  const cols = pizza[0].length;
  const apples = Array.from({ length: rows + 1 }, () => new Array(cols + 1).fill(0));
  for (let r = rows - 1; r >= 0; r--) {
    for (let c = cols - 1; c >= 0; c--) {
      const here = pizza[r][c] === 'A' ? 1 : 0;
      apples[r][c] = here + apples[r + 1][c] + apples[r][c + 1] - apples[r + 1][c + 1];
    }
  }
  let dp = apples.map(row => row.map(count => (count > 0 ? 1 : 0)));
  for (let pieces = 2; pieces <= k; pieces++) {
    const next = Array.from({ length: rows + 1 }, () => new Array(cols + 1).fill(0));
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        let total = 0;
        for (let cut = r + 1; cut < rows; cut++) {
          if (apples[r][c] - apples[cut][c] > 0) {
            total = (total + dp[cut][c]) % MOD;
          }
        }
        for (let cut = c + 1; cut < cols; cut++) {
          if (apples[r][c] - apples[r][cut] > 0) {
            total = (total + dp[r][cut]) % MOD;
          }
        }
        next[r][c] = total;
      }
    }
    dp = next;
  }
  return dp[0][0];
}

