function ways(pizza, k) {
  const rows = pizza.length, cols = pizza[0].length;
  // Scan the rectangle rows [r1, r2) by columns [c1, c2) cell by cell.
  const hasApple = (r1, c1, r2, c2) => {
    for (let r = r1; r < r2; r++) for (let c = c1; c < c2; c++) if (pizza[r][c] === 'A') return true;
    return false;
  };
  // Try every sequence of cuts without any memo.
  const count = (top, leftCol, left) => {
    if (left === 1) return hasApple(top, leftCol, rows, cols) ? 1 : 0;
    let total = 0;
    for (let cut = top + 1; cut < rows; cut++) if (hasApple(top, leftCol, cut, cols)) total += count(cut, leftCol, left - 1);
    for (let cut = leftCol + 1; cut < cols; cut++) if (hasApple(top, leftCol, rows, cut)) total += count(top, cut, left - 1);
    return total;
  };
  return count(0, 0, k) % 1000000007;
}

