function generate(rand, size) {
  const large = size === 'large';
  const rows = large ? 40 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 5);
  const cols = large ? 40 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 5);
  const densities = large ? [1, 0.6, 0.15, 0.03] : [1, 0.7, 0.4, 0.15, 0];
  const density = densities[Math.floor(rand() * densities.length)];
  const k = large ? 5 + Math.floor(rand() * 6) : 1 + Math.floor(rand() * 5);
  const pizza = [];
  for (let r = 0; r < rows; r++) {
    let row = '';
    for (let c = 0; c < cols; c++) row += rand() < density ? 'A' : '.';
    pizza.push(row);
  }
  return [pizza, k];
}
